def is_semiperfect_number(n):
    divisors = [d for d in range(1, n) if n % d == 0]
    total = sum(divisors)
    if total < n:
        return False
    dp = [False] * (n + 1)
    dp[0] = True
    for d in divisors:
        for s in range(n, d - 1, -1):
            if dp[s - d]:
                dp[s] = True
    return dp[n]

def sum_divisors(n):
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            j = n // i
            total += i
            if j != i:
                total += j
        i += 1
    return total

def count_distinct_prime_factors(n):
    count = 0
    d = 2
    while d * d <= n:
        if n % d == 0:
            count += 1
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        count += 1
    return count

def count_prime_factors_with_multiplicity(n):
