def recaman(n):
    seq = [0]
    seen = {0}
    for k in range(1, n + 1):
        prev = seq[-1]
        candidate = prev - k
        if candidate > 0 and candidate not in seen:
            val = candidate
        else:
            val = prev + k
        seq.append(val)
        seen.add(val)
    return seq[n]

