def is_sum_of_two_squares(n):
    a = 0
    while a * a <= n:
        rem = n - a * a
        b = math.isqrt(rem)
        if b * b == rem:
            return True
        a += 1
    return False

def digital_root_base(n, b):
    while n >= b:
        total = 0
        x = n
        while x > 0:
            total += x % b
            x //= b
        n = total
    return n

def is_self_number(n):
    def digit_sum(x):
        return sum(int(c) for c in str(x))
    for m in range(0, n):
        if m + digit_sum(m) == n:
            return False
    return True

def is_emirp(n):
