        if x < 2:
            return False
        i = 2
        while i * i <= x:
            if x % i == 0:
                return False
            i += 1
        return True
    if not is_prime(n):
        return False
    reversed_n = int(str(n)[::-1])
    if reversed_n == n:
        return False
    return is_prime(reversed_n)

def sum_twin_primes_below(n):
    def is_prime(x):
        if x < 2:
            return False
        i = 2
        while i * i <= x:
            if x % i == 0:
                return False
            i += 1
        return True
    total = 0
    for p in range(2, n):
        if is_prime(p) and (is_prime(p - 2) or is_prime(p + 2)):
            total += p
    return total

def prime_gap(n):
    def is_prime(x):
        if x < 2:
            return False
        i = 2
        while i * i <= x:
            if x % i == 0:
                return False
            i += 1
        return True
    primes = []
    candidate = 2
    while len(primes) < n + 1:
        if is_prime(candidate):
            primes.append(candidate)
        candidate += 1
    return primes[n] - primes[n - 1]

def fibonacci_index(n):
    a, b = 0, 1
    k = 0
    while a < n:
        a, b = b, a + b
        k += 1
    if a == n:
        return k
    return -1
